	/**
	 * Set the tick recorder for live view updates.
	 */
	public void setTickRecorder(TickRecorder tickRecorder)
	{
		this.tickRecorder = tickRecorder;
		updateLiveSaveButtonState();
	}

	/**
	 * Toggle between recordings view and live view.
	 */
	private void toggleView()
	{
		if (!liveViewEnabled)
		{
			return;
		}

		if (currentView.equals(RECORDINGS_VIEW))
		{
			currentView = LIVE_VIEW;
			toggleViewBtn.setText("Recordings");
			toggleViewBtn.setToolTipText("Switch to recordings list view");
			cardLayout.show(contentPanel, LIVE_VIEW);
			refreshLiveTimeline();
		}
		else if (currentView.equals(LIVE_VIEW))
		{
			currentView = RECORDINGS_VIEW;
			toggleViewBtn.setText("Live View");
			toggleViewBtn.setToolTipText("Switch to live timeline view");
			cardLayout.show(contentPanel, RECORDINGS_VIEW);
		}
		// If in playback view, toggle goes to recordings view
		else if (currentView.equals(PLAYBACK_VIEW))
		{
			returnFromPlayback();
		}
	}

	/**
	 * Show the playback view for a recording.
	 */
	private void showPlayback(TickRecording recording)
	{
		previousView = currentView;
		currentView = PLAYBACK_VIEW;
		toggleViewBtn.setText("Recordings");
		toggleViewBtn.setToolTipText("Return to recordings list");
		playbackPanel.loadRecording(recording);
		cardLayout.show(contentPanel, PLAYBACK_VIEW);
	}

	/**
	 * Return from playback view to previous view.
	 */
	private void returnFromPlayback()
	{
		currentView = RECORDINGS_VIEW; // Always return to recordings view
		toggleViewBtn.setText("Live View");
		toggleViewBtn.setToolTipText("Switch to live timeline view");
		cardLayout.show(contentPanel, RECORDINGS_VIEW);
	}

	/**
	 * Toggle live updates on/off.
	 */
	private void toggleLiveUpdates()
	{
		liveRecording = !liveRecording;
		if (liveRecording)
		{
			liveStartStopBtn.setText("Pause");
			liveStatusLabel.setText("Recording: Active");
			liveStatusLabel.setForeground(new Color(80, 200, 80));
			pausedSnapshot = null;
			refreshLiveTimeline();
		}
		else
		{
			liveStartStopBtn.setText("Resume");
			liveStatusLabel.setText("Recording: Paused");
			liveStatusLabel.setForeground(new Color(255, 180, 80));
			if (tickRecorder != null)
			{
				pausedSnapshot = new ArrayList<>(tickRecorder.getTickHistory());
			}
			else
			{
				pausedSnapshot = Collections.emptyList();
			}
		}

		updateLiveSaveButtonState();
	}

	/**
	 * Refresh the panel - called after death recording.
	 */
	public void refresh()
	{
		refreshRecordingsList();
	}

	/**
	 * Called on each game tick to update live view.
	 */
	public void onGameTick()
	{
		if (liveViewEnabled && currentView.equals(LIVE_VIEW) && liveRecording)
		{
			SwingUtilities.invokeLater(this::refreshLiveTimeline);
		}
	}

	/**
	 * Refresh the recordings list view (deaths + saved).
	 */
	private void refreshRecordingsList()
	{
		recordingsListContainer.removeAll();

		List<TickRecording> deaths = recordingStorage.getDeaths();
		List<TickRecording> saved = recordingStorage.getSavedRecordings();

		GridBagConstraints gbc = new GridBagConstraints();
		gbc.gridx = 0;
		gbc.gridy = 0;
		gbc.weightx = 1.0;
		gbc.fill = GridBagConstraints.HORIZONTAL;
		gbc.anchor = GridBagConstraints.NORTH;
		gbc.insets = new Insets(3, 0, 3, 0);

		boolean hasContent = false;

		// === Recent Deaths Section (shown first - limited list) ===
		if (!deaths.isEmpty())
		{
			hasContent = true;
			JPanel deathsHeader = createSectionHeader("☠ Recent Deaths (" + deaths.size() + ")", new Color(180, 80, 80));
			recordingsListContainer.add(deathsHeader, gbc);
			gbc.gridy++;

			for (int i = 0; i < deaths.size(); i++)
			{
				TickRecording death = deaths.get(i);
				RecordingEntryPanel entryPanel = new RecordingEntryPanel(
					death, i + 1,
					this::exportRecording,
					this::deleteDeath,
					this::showPlayback,
					this::saveRecording,  // Save callback to move to saved
					this::renameRecording,
					spriteManager,
					false  // isSaved = false
				);
				recordingsListContainer.add(entryPanel, gbc);
				gbc.gridy++;
			}

			// Add spacing between sections
			if (!saved.isEmpty())
			{
				recordingsListContainer.add(Box.createVerticalStrut(10), gbc);
				gbc.gridy++;
			}
		}

		// === Saved Recordings Section ===
		if (!saved.isEmpty())
		{
			hasContent = true;
			JPanel savedHeader = createSectionHeader("Saved Recordings (" + saved.size() + ")", new Color(80, 150, 80));
			recordingsListContainer.add(savedHeader, gbc);
			gbc.gridy++;

			for (int i = 0; i < saved.size(); i++)
			{
				TickRecording recording = saved.get(i);
				RecordingEntryPanel entryPanel = new RecordingEntryPanel(
					recording, i + 1,
					this::exportRecording,
					this::deleteSavedRecording,
					this::showPlayback,
					null, // No save callback for already-saved items
					this::renameRecording,
					spriteManager,
					true  // isSaved = true
				);
				recordingsListContainer.add(entryPanel, gbc);
				gbc.gridy++;
			}
		}

		// Empty state
		if (!hasContent)
		{
			gbc.weighty = 1.0;
			recordingsListContainer.add(noRecordingsLabel, gbc);
		}
		else
		{
			gbc.weighty = 1.0;
			recordingsListContainer.add(Box.createVerticalGlue(), gbc);
		}

		recordingsListContainer.revalidate();
		recordingsListContainer.repaint();
	}

	/**
	 * Create a section header label.
	 */
	private JPanel createSectionHeader(String text, Color color)
	{
		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setBorder(new EmptyBorder(6, 10, 6, 10));

		JLabel label = new JLabel(text);
		label.setForeground(color);
		label.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 13));
		header.add(label, BorderLayout.WEST);

		return header;
	}

	/**
	 * Refresh the live timeline view.
	 */
	private void refreshLiveTimeline()
	{
		if (tickRecorder == null)
		{
			return;
		}

		liveTimelineContainer.removeAll();

		List<TickData> ticks = tickRecorder.getTickHistoryReversed();

		GridBagConstraints gbc = new GridBagConstraints();
		gbc.gridx = 0;
		gbc.gridy = 0;
		gbc.weightx = 1.0;
		gbc.fill = GridBagConstraints.HORIZONTAL;
		gbc.anchor = GridBagConstraints.NORTH;
		gbc.insets = new Insets(1, 0, 1, 0);

		if (ticks.isEmpty())
		{
			JLabel emptyLabel = new JLabel("No ticks recorded yet");
			emptyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			emptyLabel.setBorder(new EmptyBorder(20, 10, 20, 10));
			gbc.weighty = 1.0;
			liveTimelineContainer.add(emptyLabel, gbc);
		}
		else
		{
			// Update status with tick count
			int tickCount = tickRecorder.getTickCount();
			int currentTick = tickRecorder.getCurrentTickNumber();
			String statusText = liveRecording ? "Recording: Active" : "Recording: Paused";
			statusText += " (" + tickCount + " ticks, #" + currentTick + ")";
			liveStatusLabel.setText(statusText);

			int rowIndex = 0;
			for (TickData tick : ticks)
			{
				JPanel tickPanel = LiveTickPanel.createTickPanel(tick, rowIndex, spriteManager);
				liveTimelineContainer.add(tickPanel, gbc);
				gbc.gridy++;
				rowIndex++;
			}

			gbc.weighty = 1.0;
			liveTimelineContainer.add(Box.createVerticalGlue(), gbc);
		}

		liveTimelineContainer.revalidate();
		liveTimelineContainer.repaint();
		updateLiveSaveButtonState();
	}

	private void updateLiveSaveButtonState()
	{
		if (liveSaveBtn == null)
		{
			return;
		}

		if (liveSaveFeedbackActive)
		{
			// While feedback is active, keep current text/enabled state.
			return;
		}

		boolean hasPausedSnapshot = pausedSnapshot != null && !pausedSnapshot.isEmpty();
		boolean hasLiveTicks = tickRecorder != null && tickRecorder.getTickCount() > 0;
		liveSaveBtn.setEnabled(hasPausedSnapshot || hasLiveTicks);
		liveSaveBtn.setText(LIVE_SAVE_DEFAULT_TEXT);
	}

	/**
	 * Export a recording to clipboard.
	 */
	private void exportRecording(TickRecording recording)
	{
		String json = recordingStorage.exportRecordingAsJson(recording);
		copyToClipboard(json);
		JOptionPane.showMessageDialog(
			this,
			"Recording exported to clipboard!",
			"Export Successful",
			JOptionPane.INFORMATION_MESSAGE
		);
	}

	/**
	 * Delete a death record.
	 */
	private void deleteDeath(TickRecording death)
	{
		int result = JOptionPane.showConfirmDialog(
			this,
			"Delete this death record?",
			"Confirm Delete",
			JOptionPane.YES_NO_OPTION
		);
		if (result == JOptionPane.YES_OPTION)
		{
			recordingStorage.deleteDeath(death);
			refreshRecordingsList();
		}
	}

	/**
	 * Save a recording to the saved recordings list.
	 */
	private void saveRecording(TickRecording recording)
	{
		recordingStorage.saveRecording(recording);
		refreshRecordingsList();
		JOptionPane.showMessageDialog(
			this,
			"Recording saved! It will no longer auto-delete.",
			"Saved",
			JOptionPane.INFORMATION_MESSAGE
		);
	}

	/**
	 * Rename a recording (applies to both saved and recent entries).
	 */
	private void renameRecording(TickRecording recording)
	{
		if (recording == null)
		{
			return;
		}

		String currentName = recording.getKillerName();
		String newName = (String) JOptionPane.showInputDialog(
			this,
			"Enter a new name:",
			"Rename Recording",
			JOptionPane.PLAIN_MESSAGE,
			null,
			null,
			currentName
		);

		if (newName == null)
		{
			return;
		}

		String trimmed = newName.trim();
		if (trimmed.isEmpty() || trimmed.equals(currentName))
		{
			return;
		}

		recordingStorage.renameRecording(recording, trimmed);
		refreshRecordingsList();
	}

	/**
	 * Delete a saved recording.
	 */
	private void deleteSavedRecording(TickRecording recording)
	{
		int result = JOptionPane.showConfirmDialog(
			this,
			"Delete this saved recording?",
			"Confirm Delete",
			JOptionPane.YES_NO_OPTION
		);
		if (result == JOptionPane.YES_OPTION)
		{
			recordingStorage.deleteSavedRecording(recording);
			refreshRecordingsList();
		}
	}

	/**
	 * Export current live buffer to clipboard.
	 */
	private void exportLiveBuffer()
	{
		if (tickRecorder == null || tickRecorder.getTickCount() == 0)
		{
			JOptionPane.showMessageDialog(
				this,
				"No ticks to export!",
				"Export",
				JOptionPane.WARNING_MESSAGE
			);
			return;
		}

		List<TickData> ticks = tickRecorder.getTickHistory();
		String json = gson.toJson(ticks);
		copyToClipboard(json);
		JOptionPane.showMessageDialog(
			this,
			"Live buffer (" + ticks.size() + " ticks) exported to clipboard!",
			"Export Successful",
			JOptionPane.INFORMATION_MESSAGE
		);
	}

	/**
	 * Save current live buffer as a recording.
	 */
	private void saveLiveBuffer()
	{
		List<TickData> sourceTicks;
		if (pausedSnapshot != null)
		{
			sourceTicks = new ArrayList<>(pausedSnapshot);
		}
		else if (tickRecorder != null && tickRecorder.getTickCount() > 0)
		{
			sourceTicks = new ArrayList<>(tickRecorder.getTickHistory());
		}
		else
		{
			JOptionPane.showMessageDialog(
				this,
				"No ticks recorded yet. Play for a bit before saving.",
				"Save",
				JOptionPane.WARNING_MESSAGE
			);
			return;
		}

		String name = "Live Snapshot - " + LocalDateTime.now().format(SNAPSHOT_FORMAT);

		int totalDamage = TickRecording.calculateTotalDamage(sourceTicks);

		TickRecording recording = TickRecording.builder()
			.timestamp(System.currentTimeMillis())
			.killerName(name.trim())
			.location("Live Snapshot")
			.ticks(sourceTicks)
			.finalHp(sourceTicks.isEmpty() ? 0 : sourceTicks.get(sourceTicks.size() - 1).getCurrentHp())
			.totalDamageReceived(totalDamage)
			.build();

		recordingStorage.addSavedRecording(recording);
		refreshRecordingsList();
		showLiveSaveFeedback();
	}

	/**
	 * Copy text to system clipboard.
	 */
	private void copyToClipboard(String text)
	{
		Toolkit.getDefaultToolkit()
			.getSystemClipboard()
			.setContents(new StringSelection(text), null);
	}

	private void showLiveSaveFeedback()
	{
		if (liveSaveBtn == null)
		{
			return;
		}

		if (liveSaveFeedbackTimer != null && liveSaveFeedbackTimer.isRunning())
		{
			liveSaveFeedbackTimer.stop();
		}

		liveSaveFeedbackActive = true;
		liveSaveBtn.setText("Saved!");
		liveSaveBtn.setEnabled(false);

		liveSaveFeedbackTimer = new Timer(LIVE_SAVE_FEEDBACK_DURATION_MS, e ->
		{
			liveSaveFeedbackActive = false;
			liveSaveBtn.setText(LIVE_SAVE_DEFAULT_TEXT);
			updateLiveSaveButtonState();
		});
		liveSaveFeedbackTimer.setRepeats(false);
		liveSaveFeedbackTimer.start();
	}

	/**
	 * Enable or disable live view (configuration controlled).
	 */
	public void setLiveViewEnabled(boolean enabled)
	{
		liveViewEnabled = enabled;
		toggleViewBtn.setEnabled(enabled);
		if (enabled)
		{
			toggleViewBtn.setText(currentView.equals(LIVE_VIEW) ? "Recordings" : "Live View");
			toggleViewBtn.setToolTipText("Switch to live timeline view");
		}
		else
		{
			toggleViewBtn.setText("Live View (disabled)");
			toggleViewBtn.setToolTipText("Enable Live View in the config to use this feature");
			if (currentView.equals(LIVE_VIEW) || currentView.equals(PLAYBACK_VIEW))
			{
				currentView = RECORDINGS_VIEW;
				cardLayout.show(contentPanel, RECORDINGS_VIEW);
			}
		}
	}
}

package com.tickreplaylogger.ui;

import com.tickreplaylogger.model.DamageEvent;
import com.tickreplaylogger.model.MovementData;
import com.tickreplaylogger.model.PlayerAction;
import com.tickreplaylogger.model.TickData;
import net.runelite.api.SpriteID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.concurrent.atomic.AtomicReference;

/**
 * Utility class for creating tick panels in the live timeline view.
 */
public class LiveTickPanel
{
	private static final Color DAMAGE_RECEIVED_COLOR = new Color(255, 100, 100);
	private static final Color DAMAGE_DEALT_COLOR = new Color(100, 255, 100);
	private static final Color ACTION_COLOR = new Color(255, 200, 100);
	private static final Color PRAYER_COLOR = new Color(150, 150, 255);
	private static final Color MOVEMENT_COLOR = new Color(100, 200, 255);
	private static final Color HP_LOW_COLOR = new Color(255, 80, 80);
	private static final Color HP_MED_COLOR = new Color(255, 180, 80);
	private static final Color HP_HIGH_COLOR = new Color(80, 200, 80);

	// Alternating row colors
	private static final Color ROW_COLOR_1 = ColorScheme.DARK_GRAY_COLOR;
	private static final Color ROW_COLOR_2 = new Color(45, 45, 45);

	private static final int ICON_SIZE = 18;

	// Cached icons - shared across all panels
	private static final AtomicReference<ImageIcon> iconHitpoints = new AtomicReference<>();
	private static final AtomicReference<ImageIcon> iconPrayer = new AtomicReference<>();
	private static final AtomicReference<ImageIcon> iconAttack = new AtomicReference<>();
	private static final AtomicReference<ImageIcon> iconAgility = new AtomicReference<>();

	private static volatile boolean iconsLoaded = false;

	/**
	 * Load sprite icons if not already loaded.
	 */
	public static void loadSprites(SpriteManager spriteManager)
	{
		if (iconsLoaded)
		{
			return;
		}

		spriteManager.getSpriteAsync(SpriteID.SKILL_HITPOINTS, 0, img -> {
			iconHitpoints.set(scaleIcon(img));
		});

		spriteManager.getSpriteAsync(SpriteID.SKILL_PRAYER, 0, img -> {
			iconPrayer.set(scaleIcon(img));
		});

		spriteManager.getSpriteAsync(SpriteID.SKILL_ATTACK, 0, img -> {
			iconAttack.set(scaleIcon(img));
		});

		spriteManager.getSpriteAsync(SpriteID.SKILL_AGILITY, 0, img -> {
			iconAgility.set(scaleIcon(img));
		});

		iconsLoaded = true;
	}

	private static ImageIcon scaleIcon(BufferedImage img)
	{
		if (img == null)
		{
			return null;
		}
		Image scaled = img.getScaledInstance(ICON_SIZE, ICON_SIZE, Image.SCALE_SMOOTH);
		return new ImageIcon(scaled);
	}

	/**
	 * Create a panel displaying a single tick's data for the live view.
	 *
	 * @param tick         The tick data to display
	 * @param rowIndex     The row index for alternating colors
	 * @param spriteManager The sprite manager for loading icons
	 * @return A JPanel containing the tick display
	 */
	public static JPanel createTickPanel(TickData tick, int rowIndex, SpriteManager spriteManager)
	{
		// Ensure sprites are loaded
		loadSprites(spriteManager);

		JPanel panel = new JPanel(new GridBagLayout());

		// Alternating row colors
		Color bgColor = (rowIndex % 2 == 0) ? ROW_COLOR_1 : ROW_COLOR_2;
		panel.setBackground(bgColor);
		panel.setBorder(new EmptyBorder(4, 6, 4, 6));

		GridBagConstraints gbc = new GridBagConstraints();
		gbc.gridx = 0;
		gbc.gridy = 0;
		gbc.weightx = 1.0;
		gbc.fill = GridBagConstraints.HORIZONTAL;
		gbc.anchor = GridBagConstraints.WEST;

		// Calculate HP color
		float hpPercent = tick.getMaxHp() > 0 ? (float) tick.getCurrentHp() / tick.getMaxHp() : 0;
		Color hpColor = hpPercent > 0.5 ? HP_HIGH_COLOR : (hpPercent > 0.25 ? HP_MED_COLOR : HP_LOW_COLOR);

		// Header: tick number, prayer, and HP
		String tickLabel = "#" + tick.getTickNumber();
		String hpText = tick.getCurrentHp() + "/" + tick.getMaxHp();
		String prayerText = tick.getCurrentPrayer() + "/" + tick.getMaxPrayer();

		JPanel headerPanel = new JPanel(new BorderLayout());
		headerPanel.setBackground(bgColor);

		JLabel tickLbl = new JLabel(tickLabel);
		tickLbl.setForeground(Color.WHITE);
		tickLbl.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 13));
		headerPanel.add(tickLbl, BorderLayout.WEST);

		// Right side panel for prayer and HP
		JPanel statsPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 8, 0));
		statsPanel.setBackground(bgColor);

		// Prayer points label
		JLabel prayerLbl = new JLabel(prayerText);
		prayerLbl.setForeground(PRAYER_COLOR);
		prayerLbl.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 13));
		if (iconPrayer.get() != null)
		{
			prayerLbl.setIcon(iconPrayer.get());
			prayerLbl.setHorizontalTextPosition(SwingConstants.LEFT);
		}
		statsPanel.add(prayerLbl);

		// HP label
		JLabel hpLbl = new JLabel(hpText);
		hpLbl.setForeground(hpColor);
		hpLbl.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 13));
		if (iconHitpoints.get() != null)
		{
			hpLbl.setIcon(iconHitpoints.get());
			hpLbl.setHorizontalTextPosition(SwingConstants.LEFT);
		}
		statsPanel.add(hpLbl);

		headerPanel.add(statsPanel, BorderLayout.EAST);

		panel.add(headerPanel, gbc);
		gbc.gridy++;

		// Content
		boolean hasContent = false;

		// Active prayers - each on its own line
		for (String prayer : tick.getActivePrayers())
		{
			JLabel label = createIconLabel(prayer, iconPrayer.get(), PRAYER_COLOR);
			panel.add(label, gbc);
			gbc.gridy++;
			hasContent = true;
		}

		// Movement
		MovementData movement = tick.getMovement();
		if (movement != null && movement.hasMovement())
		{
			String moveDesc = movement.getDescription();
			if (moveDesc != null)
			{
				JLabel label = createIconLabel(moveDesc, iconAgility.get(), MOVEMENT_COLOR);
				panel.add(label, gbc);
				gbc.gridy++;
				hasContent = true;
			}
		}

		// Player actions
		for (PlayerAction action : tick.getPlayerActions())
		{
			ImageIcon icon = getActionIcon(action);
			JLabel label = createIconLabel(action.getDescription(), icon, ACTION_COLOR);
			panel.add(label, gbc);
			gbc.gridy++;
			hasContent = true;
		}

		// Damage events
		for (DamageEvent damage : tick.getDamageEvents())
		{
			boolean isReceived = damage.getDirection() == DamageEvent.DamageDirection.RECEIVED;
			Color color = isReceived ? DAMAGE_RECEIVED_COLOR : DAMAGE_DEALT_COLOR;
			JLabel label = createIconLabel(damage.getDescription(), iconAttack.get(), color);
			panel.add(label, gbc);
			gbc.gridy++;
			hasContent = true;
		}

		// If no content, show dash
		if (!hasContent)
		{
			JLabel emptyLabel = new JLabel("-");
			emptyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			emptyLabel.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
			emptyLabel.setBorder(new EmptyBorder(1, 20, 1, 0));
			panel.add(emptyLabel, gbc);
		}

		return panel;
	}

	private static ImageIcon getActionIcon(PlayerAction action)
	{
		String desc = action.getDescription().toLowerCase();
		if (desc.startsWith("ate") || desc.startsWith("drank"))
		{
			return iconHitpoints.get();
		}
		else if (desc.contains("prayer") || desc.startsWith("activated") || desc.startsWith("deactivated") || desc.contains("disabled"))
		{
			return iconPrayer.get();
		}
		else if (desc.startsWith("equipped") || desc.startsWith("unequipped"))
		{
			return iconAttack.get();
		}
		else if (desc.startsWith("attacked") || desc.startsWith("special"))
		{
			return iconAttack.get();
		}
		return null;
	}

	private static JLabel createIconLabel(String text, ImageIcon icon, Color color)
	{
		JLabel label = new JLabel(text);
		label.setForeground(color);
		label.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
		label.setToolTipText(text);
		if (icon != null)
		{
			label.setIcon(icon);
			label.setIconTextGap(6);
			label.setBorder(new EmptyBorder(1, 4, 1, 0));
		}
		else
		{
			label.setBorder(new EmptyBorder(1, 20, 1, 0));
		}
		return label;
	}
}

package com.tickreplaylogger.util;

import com.tickreplaylogger.model.DamageEvent;
import com.tickreplaylogger.model.MovementData;
import com.tickreplaylogger.model.PlayerAction;
import com.tickreplaylogger.model.TickData;
import lombok.extern.slf4j.Slf4j;

import java.util.ArrayList;
import java.util.List;

/**
 * Circular buffer that records tick data.
 * Maintains only the last N ticks (default 50) to bound memory usage.
 * When the buffer is full, oldest ticks are overwritten.
 */
@Slf4j
public class TickRecorder
{
	private TickData[] buffer;
	private int capacity;
	private int head = 0;           // Next write position
	private int count = 0;          // Number of ticks stored
	private int currentTickNumber = 0;

	// Current tick being built (actions accumulate here until tick ends)
	private TickData currentTick;

	public TickRecorder(int capacity)
	{
		this.capacity = capacity;
		this.buffer = new TickData[capacity];
		log.debug("TickRecorder initialized with capacity: {}", capacity);
	}

	/**
	 * Resize the buffer capacity. Preserves existing data up to the new capacity.
	 */
	public void resize(int newCapacity)
	{
		if (newCapacity == capacity)
		{
			return;
		}

		// Get current history in order
		List<TickData> history = getTickHistory();

		// Create new buffer
		capacity = newCapacity;
		buffer = new TickData[newCapacity];
		head = 0;
		count = 0;

		// Copy over as many ticks as will fit (most recent ones)
		int startIndex = Math.max(0, history.size() - newCapacity);
		for (int i = startIndex; i < history.size(); i++)
		{
			buffer[head] = history.get(i);
			head = (head + 1) % capacity;
			count++;
		}

		log.debug("TickRecorder resized to capacity: {} ({} ticks preserved)", newCapacity, count);
	}

	/**
	 * Start a new tick. Call this at the beginning of each GameTick.
	 */
	public void startNewTick()
	{
		currentTickNumber++;
		currentTick = TickData.builder()
			.tickNumber(currentTickNumber)
			.timestamp(System.currentTimeMillis())
			.playerActions(new ArrayList<>())
			.damageEvents(new ArrayList<>())
			.activePrayers(new ArrayList<>())
			.build();
	}

	/**
	 * Finalize the current tick and add it to the buffer.
	 * Call this at the end of each GameTick after state snapshot.
	 */
	public void finalizeTick()
	{
		if (currentTick == null)
		{
			log.warn("finalizeTick called but no current tick exists");
			return;
		}

		// Add to circular buffer
		buffer[head] = currentTick;
		head = (head + 1) % capacity;
		if (count < capacity)
		{
			count++;
		}

		log.debug("Tick {} recorded. HP: {}/{}, Prayer: {}/{}",
			currentTick.getTickNumber(),
			currentTick.getCurrentHp(),
			currentTick.getMaxHp(),
			currentTick.getCurrentPrayer(),
			currentTick.getMaxPrayer());
	}

	/**
	 * Update the current tick's state snapshot.
	 */
	public void updateState(int currentHp, int maxHp, int currentPrayer, int maxPrayer, List<String> activePrayers)
	{
		if (currentTick == null)
		{
			return;
		}
		currentTick.setCurrentHp(currentHp);
		currentTick.setMaxHp(maxHp);
		currentTick.setCurrentPrayer(currentPrayer);
		currentTick.setMaxPrayer(maxPrayer);
		currentTick.setActivePrayers(activePrayers != null ? new ArrayList<>(activePrayers) : new ArrayList<>());
	}

	/**
	 * Add a player action to the current tick.
	 */
	public void addPlayerAction(PlayerAction action)
	{
		if (currentTick == null)
		{
			log.warn("Cannot add player action - no current tick");
			return;
		}
		currentTick.addPlayerAction(action);
		log.debug("Player action added: {}", action.getDescription());
	}

	/**
	 * Add a damage event to the current tick.
	 */
	public void addDamageEvent(DamageEvent event)
	{
		if (currentTick == null)
		{
			log.warn("Cannot add damage event - no current tick");
			return;
		}
		currentTick.addDamageEvent(event);
		log.debug("Damage event added: {}", event.getDescription());
	}

	/**
	 * Set movement data for the current tick.
	 */
	public void setMovement(MovementData movement)
	{
		if (currentTick == null)
		{
			return;
		}
		currentTick.setMovement(movement);
		if (movement != null && movement.hasMovement())
		{
			log.debug("Movement recorded: {}", movement.getDescription());
		}
	}

	/**
	 * Get all recorded ticks in chronological order (oldest first).
	 * Returns a copy of the data.
	 */
	public List<TickData> getTickHistory()
	{
		List<TickData> history = new ArrayList<>(count);

		if (count == 0)
		{
			return history;
		}

		// Calculate starting position (oldest tick)
		int start = (count < capacity) ? 0 : head;

		for (int i = 0; i < count; i++)
		{
			int index = (start + i) % capacity;
			if (buffer[index] != null)
			{
				history.add(buffer[index]);
			}
		}

		return history;
	}

	/**
	 * Get recorded ticks in reverse chronological order (newest first).
	 * This is the order we display in the UI.
	 */
	public List<TickData> getTickHistoryReversed()
	{
		List<TickData> history = getTickHistory();
		List<TickData> reversed = new ArrayList<>(history.size());
		for (int i = history.size() - 1; i >= 0; i--)
		{
			reversed.add(history.get(i));
		}
		return reversed;
	}

	/**
	 * Get the number of ticks currently stored.
	 */
	public int getTickCount()
	{
		return count;
	}

	/**
	 * Get the current tick number.
	 */
	public int getCurrentTickNumber()
	{
		return currentTickNumber;
	}

	/**
	 * Clear all recorded ticks.
	 */
	public void clear()
	{
		for (int i = 0; i < capacity; i++)
		{
			buffer[i] = null;
		}
		head = 0;
		count = 0;
		currentTick = null;
		log.debug("TickRecorder cleared");
	}

	/**
	 * Reset tick counter (e.g., on login).
	 */
	public void resetTickCounter()
	{
		currentTickNumber = 0;
		clear();
		log.debug("Tick counter reset");
	}
}

package com.tickreplaylogger.util;

import com.tickreplaylogger.model.TickRecording;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;

/**
 * Handles persistence of tick recordings to JSON files.
 * Deaths are stored in ~/.runelite/tick-replay-logger/deaths.json
 * Saved recordings are stored in ~/.runelite/tick-replay-logger/saved.json
 */
@Slf4j
public class RecordingStorage
{
	private static final String FOLDER_NAME = "tick-replay-logger";
	private static final String DEATHS_FILE_NAME = "deaths.json";
	private static final String SAVED_FILE_NAME = "saved.json";

	private final Gson gson;
	private final File deathsFile;
	private final File savedFile;
	private int maxDeaths;

	private List<TickRecording> deaths;
	private List<TickRecording> savedRecordings;

	public RecordingStorage(int maxDeaths, Gson gson)
	{
		this.maxDeaths = maxDeaths;
		this.gson = gson.newBuilder()
			.setPrettyPrinting()
			.create();

		// Create storage directory
		File folder = new File(RuneLite.RUNELITE_DIR, FOLDER_NAME);
		if (!folder.exists())
		{
			folder.mkdirs();
		}

		this.deathsFile = new File(folder, DEATHS_FILE_NAME);
		this.savedFile = new File(folder, SAVED_FILE_NAME);
		this.deaths = new ArrayList<>();
		this.savedRecordings = new ArrayList<>();

		// Load existing data
		loadDeaths();
		loadSavedRecordings();
	}

	/**
	 * Load deaths from JSON file
	 */
	public void loadDeaths()
	{
		if (!deathsFile.exists())
		{
			log.debug("No existing deaths file found");
			deaths = new ArrayList<>();
			return;
		}

		try (FileReader reader = new FileReader(deathsFile))
		{
			Type listType = new TypeToken<ArrayList<TickRecording>>(){}.getType();
			List<TickRecording> loaded = gson.fromJson(reader, listType);

			if (loaded != null)
			{
				deaths = loaded;
				log.debug("Loaded {} death records from file", deaths.size());
			}
			else
			{
				deaths = new ArrayList<>();
			}
		}
		catch (IOException e)
		{
			log.error("Failed to load deaths from file", e);
			deaths = new ArrayList<>();
		}
		catch (Exception e)
		{
			log.error("Failed to parse deaths file", e);
			deaths = new ArrayList<>();
		}
	}

	/**
	 * Load saved recordings from JSON file
	 */
	public void loadSavedRecordings()
	{
		if (!savedFile.exists())
		{
			log.debug("No existing saved recordings file found");
			savedRecordings = new ArrayList<>();
			return;
		}

		try (FileReader reader = new FileReader(savedFile))
		{
			Type listType = new TypeToken<ArrayList<TickRecording>>(){}.getType();
			List<TickRecording> loaded = gson.fromJson(reader, listType);

			if (loaded != null)
			{
				savedRecordings = loaded;
				log.debug("Loaded {} saved recordings from file", savedRecordings.size());
			}
			else
			{
				savedRecordings = new ArrayList<>();
			}
		}
		catch (IOException e)
		{
			log.error("Failed to load saved recordings from file", e);
			savedRecordings = new ArrayList<>();
		}
		catch (Exception e)
		{
			log.error("Failed to parse saved recordings file", e);
			savedRecordings = new ArrayList<>();
		}
	}

	/**
	 * Save deaths to JSON file
	 */
	public void saveDeaths()
	{
		try (FileWriter writer = new FileWriter(deathsFile))
		{
			gson.toJson(deaths, writer);
			log.debug("Saved {} death records to file", deaths.size());
		}
		catch (IOException e)
		{
			log.error("Failed to save deaths to file", e);
		}
	}

	/**
	 * Save saved recordings to JSON file
	 */
	public void saveSavedRecordings()
	{
		try (FileWriter writer = new FileWriter(savedFile))
		{
			gson.toJson(savedRecordings, writer);
			log.debug("Saved {} saved recordings to file", savedRecordings.size());
		}
		catch (IOException e)
		{
			log.error("Failed to save saved recordings to file", e);
		}
	}

	/**
	 * Add a new death record.
	 * Prunes old deaths if we exceed maxDeaths.
	 */
	public void addDeath(TickRecording death)
	{
		// Add to beginning of list (newest first)
		deaths.add(0, death);

		// Prune if we exceed max
		while (deaths.size() > maxDeaths)
		{
			deaths.remove(deaths.size() - 1);
		}

		// Save to file
		saveDeaths();

		log.debug("Death recorded: killed by {} ({} total deaths stored)",
			death.getKillerName(), deaths.size());
	}

	/**
	 * Get all stored death records (newest first)
	 */
	public List<TickRecording> getDeaths()
	{
		return new ArrayList<>(deaths);
	}

	/**
	 * Get the number of stored deaths
	 */
	public int getDeathCount()
	{
		return deaths.size();
	}

	/**
	 * Set the maximum number of deaths to store.
	 * Prunes oldest deaths if current count exceeds new max.
	 */
	public void setMaxDeaths(int newMax)
	{
		if (newMax == maxDeaths)
		{
			return;
		}

		maxDeaths = newMax;

		// Prune if we now exceed the limit
		boolean pruned = false;
		while (deaths.size() > maxDeaths)
		{
			deaths.remove(deaths.size() - 1);
			pruned = true;
		}

		if (pruned)
		{
			saveDeaths();
			log.debug("Death storage max changed to {}, pruned to {} deaths", maxDeaths, deaths.size());
		}
		else
		{
			log.debug("Death storage max changed to {}", maxDeaths);
		}
	}

	/**
	 * Clear all stored deaths
	 */
	public void clearDeaths()
	{
		deaths.clear();
		saveDeaths();
		log.debug("All death records cleared");
	}

	/**
	 * Delete a specific death record
	 */
	public void deleteDeath(TickRecording death)
	{
		if (deaths.remove(death))
		{
			saveDeaths();
			log.debug("Death record deleted: killed by {}", death.getKillerName());
		}
	}

	/**
	 * Delete a death by index
	 */
	public void deleteDeath(int index)
	{
		if (index >= 0 && index < deaths.size())
		{
			TickRecording removed = deaths.remove(index);
			saveDeaths();
			log.debug("Death record deleted: killed by {}", removed.getKillerName());
		}
	}

	/**
	 * Export all deaths as JSON string (for clipboard)
	 */
	public String exportAllAsJson()
	{
		return gson.toJson(deaths);
	}

	/**
	 * Export a single death as JSON string (for clipboard)
	 */
	public String exportRecordingAsJson(TickRecording recording)
	{
		return gson.toJson(recording);
	}

	/**
	 * Export a single death by index as JSON string
	 */
	public String exportDeathAsJson(int index)
	{
		if (index >= 0 && index < deaths.size())
		{
			return gson.toJson(deaths.get(index));
		}
		return "{}";
	}

	// ===== SAVED RECORDINGS =====

	/**
	 * Get all saved recordings (newest first)
	 */
	public List<TickRecording> getSavedRecordings()
	{
		return new ArrayList<>(savedRecordings);
	}

	/**
	 * Get the number of saved recordings
	 */
	public int getSavedCount()
	{
		return savedRecordings.size();
	}

	/**
	 * Save a death - moves it from deaths list to saved recordings (no auto-delete)
	 */
	public void saveRecording(TickRecording death)
	{
		if (deaths.remove(death))
		{
			savedRecordings.add(0, death);
			saveDeaths();
			saveSavedRecordings();
			log.debug("Death saved to permanent recordings: {}", death.getKillerName());
		}
	}

	/**
	 * Add a new saved recording directly (e.g., from live view snapshot)
	 * No limit on saved recordings.
	 */
	public void addSavedRecording(TickRecording recording)
	{
		savedRecordings.add(0, recording);
		saveSavedRecordings();
		log.debug("Recording saved: {}", recording.getKillerName());
	}

	/**
	 * Rename a recording (applies to both recent deaths and saved recordings).
	 */
	public void renameRecording(TickRecording recording, String newName)
	{
		if (recording == null || newName == null)
		{
			return;
		}
		String trimmed = newName.trim();
		if (trimmed.isEmpty())
		{
			return;
		}

		recording.setKillerName(trimmed);
		saveDeaths();
		saveSavedRecordings();
		log.debug("Recording renamed to {}", trimmed);
	}

	/**
	 * Delete a specific saved recording
	 */
	public void deleteSavedRecording(TickRecording recording)
	{
		if (savedRecordings.remove(recording))
		{
			saveSavedRecordings();
			log.debug("Saved recording deleted: {}", recording.getKillerName());
		}
	}

	/**
	 * Clear all saved recordings
	 */
	public void clearSavedRecordings()
	{
		savedRecordings.clear();
		saveSavedRecordings();
		log.debug("All saved recordings cleared");
	}

	/**
	 * Export a saved recording as JSON string
	 */
	public String exportSavedRecordingAsJson(TickRecording recording)
	{
		return gson.toJson(recording);
	}
}

